import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.fntC-tS-.js";const u=JSON.parse('{"title":"Contribute","description":"","frontmatter":{"title":"Contribute"},"headers":[],"relativePath":"contribute.md","filePath":"contribute.md","lastUpdated":1794399311000}'),n={name:"contribute.md"};function o(l,e,r,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="contribute" tabindex="-1">Contribute <a class="header-anchor" href="#contribute" aria-label="Permalink to &quot;Contribute&quot;">​</a></h1><p>This hub is a set of Markdown files in the <a href="https://github.com/Unil-SGC/unil-sgc.github.io" target="_blank" rel="noreferrer">unil-sgc.github.io</a> repository, built with <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a> and published on GitHub Pages. Anyone with a GitHub account can propose a change.</p><h2 id="edit-a-page" tabindex="-1">Edit a page <a class="header-anchor" href="#edit-a-page" aria-label="Permalink to &quot;Edit a page&quot;">​</a></h2><ol><li>Click <strong>Edit this page on GitHub</strong> at the bottom of any page.</li><li>Make your change in the GitHub editor and open a pull request.</li><li>The pull request builds the site. Once it is merged into <code>main</code>, the site is deployed within a few minutes.</li></ol><p>Pages live in the <code>docs/</code> folder. The folder structure gives the URL: <code>docs/data/catalogues.md</code> is served at <code>/data/catalogues</code>.</p><h2 id="add-a-news-item-or-an-event" tabindex="-1">Add a news item or an event <a class="header-anchor" href="#add-a-news-item-or-an-event" aria-label="Permalink to &quot;Add a news item or an event&quot;">​</a></h2><p>Create a Markdown file in <code>docs/news/</code> or <code>docs/events/</code>. The file name becomes the URL. Start it with this front matter, then write the content:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">title: &quot;SGC symposium 2026&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">date: 2026-11-21</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">author: &quot;Jane Doe&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tags: [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">&quot;Event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># SGC symposium 2026</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Content in Markdown ...</span></span></code></pre></div><p>The listing pages and the sidebar are generated from these files, so there is nothing else to update. Images go in <code>docs/public/images/</code> and are referenced as <code>/images/my-image.png</code>.</p><h2 id="useful-markdown-extras" tabindex="-1">Useful Markdown extras <a class="header-anchor" href="#useful-markdown-extras" aria-label="Permalink to &quot;Useful Markdown extras&quot;">​</a></h2><p>VitePress supports GitHub-flavoured Markdown plus a few extras:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: tip Title</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">A highlighted note. Also available: info, warning, danger, details.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:coffee: emoji shortcodes work, and so do tables and footnotes.</span></span></code></pre></div><p>See the <a href="https://vitepress.dev/guide/markdown" target="_blank" rel="noreferrer">VitePress Markdown reference</a> for the full list.</p><p>A thin decorative banner under a page title is one line, with an optional dark-mode variant:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;PageBanner light=&quot;/images/my-banner-light.webp&quot; dark=&quot;/images/my-banner-dark.webp&quot; alt=&quot;What the picture shows&quot; /&gt;</span></span></code></pre></div><p>Raw HTML is allowed too, with two rules: leave a blank line before and after an HTML block, and avoid deprecated tags such as <code>&lt;center&gt;</code>, which the renderer silently drops. For images, prefer the Markdown syntax <code>![description](/images/my-image.png)</code>.</p><h2 id="preview-locally" tabindex="-1">Preview locally <a class="header-anchor" href="#preview-locally" aria-label="Permalink to &quot;Preview locally&quot;">​</a></h2><p>Optional, for larger changes. You need <a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js</a> 22 or newer; a version manager such as <a href="https://github.com/Schniz/fnm" target="_blank" rel="noreferrer">fnm</a> or <a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">nvm</a> installs it in your home directory without administrator rights and picks up the version from the <code>.nvmrc</code> file of the repository.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Unil-SGC/unil-sgc.github.io</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unil-sgc.github.io</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>Then open <code>http://localhost:5173</code>. Pages reload as you save. <code>npm run docs:build</code> runs the same build as the deployment and fails on broken internal links.</p><h2 id="site-structure" tabindex="-1">Site structure <a class="header-anchor" href="#site-structure" aria-label="Permalink to &quot;Site structure&quot;">​</a></h2><ul><li><code>docs/.vitepress/config.mts</code>: navigation, sidebar and site options.</li><li><code>docs/.vitepress/theme/</code>: small theme customisations (colours, post metadata, post lists).</li><li><code>docs/public/</code>: static files copied as they are (images, favicons, redirects for old URLs).</li><li><code>.github/workflows/deploy.yml</code>: build on pull requests, build and deploy on <code>main</code>.</li></ul>`,22)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
